from collections import Counter
import re

def task_func(content):
    if content is None:
        return {}
    if not isinstance(content, str):
        content = str(content)

    # Remove the last word while preserving any trailing punctuation.
    trimmed = re.sub(r"(\b\w+(?:['-]\w+)*\b)(?=\W*$)", "", content, count=1)

    if not trimmed.strip():
        return {}

    tokens = nltk.word_tokenize(trimmed)
    if not tokens:
        return {}

    tagged_tokens = nltk.pos_tag(tokens)
    return dict(Counter(tag for _, tag in tagged_tokens))
